const d = $json;
const texto = (v) => (typeof v === 'string' ? v.trim() : '');
const fechaValida = (v) => /^\d{4}-\d{2}-\d{2}$/.test(v) &&
  new Date(v + 'T00:00:00Z').toISOString().slice(0, 10) === v;

const cliente = texto(d.nombre);
const email = texto(d.email).toLowerCase();
const entrada = texto(d.fecha_entrada);
const salida = texto(d.fecha_salida);
const tipo = texto(d.tipo_habitacion);
const n = (typeof d.huespedes === 'number' || typeof d.huespedes === 'string') ? Number(d.huespedes) : NaN;
const huespedes = Number.isInteger(n) ? n : 0;

const fechasOk = fechaValida(entrada) && fechaValida(salida);
const errores = [];
if (!cliente) errores.push('nombre es obligatorio');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errores.push('email no es valido');
if (!fechaValida(entrada)) errores.push('fecha_entrada debe tener formato AAAA-MM-DD');
if (!fechaValida(salida)) errores.push('fecha_salida debe tener formato AAAA-MM-DD');
if (fechasOk && salida <= entrada) errores.push('fecha_salida debe ser posterior a fecha_entrada');
if (huespedes < 1) errores.push('huespedes debe ser un entero mayor que 0');
if (!tipo) errores.push('tipo_habitacion es obligatorio');

const noches = (fechasOk && salida > entrada)
  ? Math.round((new Date(salida) - new Date(entrada)) / 86400000) : 0;

return { json: { valido: errores.length === 0, errores,
  Cliente: cliente, Email: email, Entrada: entrada, Salida: salida,
  Huespedes: huespedes, Tipo: tipo, Noches: noches } };
